#![allow(clippy::excessive_precision)]
//! Golden-parity test for `compute_warp` (fillWarpRows + computeWarpPrep + warpParams,
//! PARITY_TESTING.md). Reference HTML lines 2621-2735 -- domain-warped fbm
//! (the caching in JS's computeWarpPrep is a JS-side perf optimisation that
//! doesn't affect output values, so it isn't ported here).
//!
//! Small grids (5x5 to 8x6) so the golden data stays readable; real usage
//! runs at map resolution, but every cell is the same pure per-cell formula.

use cartalith_terrain::compute_warp;

#[test]
fn compute_warp_case_0() {
    let result = compute_warp(6, 5, 12345, 0.6, false);
    let (warp_x, warp_y) = result.expect("expected Some");
    let expected_x: &[f32] = &[0.0929609164595604, 0.1233324185013771, 0.09771467000246048, 0.20460252463817596, 0.28393033146858215, 0.13334183394908905, 0.12067388743162155, 0.042530305683612823, 0.019863802939653397, 0.2520121932029724, 0.1827460080385208, 0.09602422267198563, -0.01897606998682022, 0.09804227203130722, -0.030577853322029114, 0.26595011353492737, 0.28378769755363464, 0.26220670342445374, 0.02358231507241726, 0.29521024227142334, 0.03937191516160965, 0.09832777827978134, 0.09224654734134674, 0.08565328270196915, -0.010296414606273174, 0.18576200306415558, 0.19796882569789886, 0.2153550684452057, 0.23120103776454926, -0.008041465654969215];
    let expected_y: &[f32] = &[0.10159033536911011, 0.008614831604063511, 0.23991939425468445, 0.3019004166126251, 0.22461868822574615, 0.053501665592193604, 0.18466421961784363, 0.0029011492151767015, 0.18076376616954803, 0.17315778136253357, 0.3146454989910126, 0.024706721305847168, -0.010960012674331665, 0.0831298902630806, 0.13924701511859894, 0.29287195205688477, 0.33565977215766907, 0.2181343287229538, -0.10460586100816727, 0.2781447172164917, 0.21100197732448578, 0.22332912683486938, 0.26331841945648193, 0.12452524900436401, 0.1613846719264984, 0.20001794397830963, 0.27743369340896606, 0.24417686462402344, 0.28197845816612244, 0.06912542879581451];
    assert_eq!(warp_x.as_slice(), expected_x);
    assert_eq!(warp_y.as_slice(), expected_y);
}

